/** A bad request value; `message` is safe to show to the owner. */
export class ValidationError extends Error {}

const CONTROL_CHARACTERS = /[\\p{Cc}\\u2028\\u2029]/u;
const INVISIBLE_ONLY = /^[\\s\\p{Cf}]*$/u;

/**
 * Returns the title trimmed, or throws a ValidationError. Length counts characters (code points),
 * the same way the `length()` CHECK in the migration does.
 */
export function parseTitle(value: unknown): string {
  if (value === undefined || value === null) throw new ValidationError("title is required");
  if (typeof value !== "string") throw new ValidationError("title must be a string");
  if (!value.isWellFormed()) throw new ValidationError("title must be valid Unicode text");
  if (CONTROL_CHARACTERS.test(value)) {
    throw new ValidationError("title must not contain control characters or line breaks");
  }
  const title = value.trim();
  if (INVISIBLE_ONLY.test(title)) throw new ValidationError("title must not be empty");
  if ([...title].length > TITLE_MAX_LENGTH) {
    throw new ValidationError(`title must be at most ${TITLE_MAX_LENGTH} characters`);
  }
  return title;
}

